package com.logiplatform.service;
import com.logiplatform.dto.OperationsDtos.*; import com.logiplatform.model.*; import com.logiplatform.repository.*; import com.logiplatform.tenancy.TenantContext; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class WarehouseWorkflowService { private final WarehouseTaskRepository repo; private final WarehouseRepository warehouses; public WarehouseWorkflowService(WarehouseTaskRepository r,WarehouseRepository w){repo=r;warehouses=w;}
 @Transactional public WarehouseTaskResponse create(WarehouseTaskRequest r){UUID t=TenantContext.getTenantId(); warehouses.findByIdAndTenantId(r.warehouseId(),t).orElseThrow(()->nf("Warehouse not found")); return WarehouseTaskResponse.from(repo.save(new WarehouseTask(t,r.warehouseId(),r.shipmentId(),r.inventoryItemId(),r.taskType().toUpperCase(),r.quantity(),r.sourceLocation(),r.destinationLocation(),r.assignedTo(),r.dueAt(),r.notes())));}
 @Transactional(readOnly=true) public List<WarehouseTaskResponse> list(UUID warehouseId,String status){UUID t=TenantContext.getTenantId(); warehouses.findByIdAndTenantId(warehouseId,t).orElseThrow(()->nf("Warehouse not found")); List<WarehouseTask> xs=status==null?repo.findAllByTenantIdAndWarehouseIdOrderByCreatedAtDesc(t,warehouseId):repo.findAllByTenantIdAndStatusOrderByDueAtAsc(t,status.toUpperCase()); return xs.stream().filter(x->warehouseId.equals(x.getWarehouseId())).map(WarehouseTaskResponse::from).toList();}
 @Transactional public WarehouseTaskResponse start(UUID id){WarehouseTask x=owned(id);x.start();return WarehouseTaskResponse.from(repo.save(x));} @Transactional public WarehouseTaskResponse complete(UUID id){WarehouseTask x=owned(id);x.complete();return WarehouseTaskResponse.from(repo.save(x));} @Transactional public WarehouseTaskResponse cancel(UUID id){WarehouseTask x=owned(id);x.cancel();return WarehouseTaskResponse.from(repo.save(x));}
 private WarehouseTask owned(UUID id){return repo.findByIdAndTenantId(id,TenantContext.getTenantId()).orElseThrow(()->nf("Warehouse task not found"));} private static ResponseStatusException nf(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);} }
